où $\alpha^*_{n,p}:E_n^*\longrightarrow E_p^*$\quad$(n>p\geq1)$
\uline{défini par}
$\boxed{\alpha_{n,p}^*=\partial_p^*\partial_{p+1}^*\cdots\partial_{n-1}^*}$
\diagram{\begin{tikzcd}[column sep=small]
E_n^* \arrow[r,"\partial_{n-1}^*"] & E_{n-1}^* \arrow[r,"\partial_{\unsure{n-2}}^*"] & E_{n-2}^*\ \cdots \arrow[r,"\partial_p^*"] & E_p^*
\end{tikzcd}}

$\beta_{n,q}^*:E_n^*\longrightarrow E_q^*$\quad$(n\unsure{\geq}q\geq1)$
\uline{défini par}
$\boxed{\beta_{n,q}^*=\partial_q^{\prime *}\partial_{q+1}^{\prime *}\cdots\partial_{n-1}^{\prime *}}$
\diagram{\begin{tikzcd}[column sep=small]
E_n^* \arrow[r,"\partial_{n-1}^{\prime *}"] & E_{n-1}^* \arrow[r,"\partial_{n-2}^{\prime *}"] & E_{n-2}^*\ \cdots \arrow[r,"\partial_q^{\prime *}"] & E_q^*
\end{tikzcd}}
